m(4,"Decline","This overload has been accompanied by a marked decline in…","Civility and argumentative complexity",["Voter turnout and party membership","Economic growth and employment","Press freedom and literacy"],"“A marked decline in civility and argumentative complexity.”");
m(4,"Vicious cycle","Which two things reinforce each other in a vicious cycle?","Uncivil elites and pathological mass communication",["Economic crisis and mass unemployment","Immigration and rising nationalism","Low turnout and political corruption"],"“Uncivil behavior by elites and pathological mass communication reinforce each other.”");
